window.MISSIONS = [{"id": "apollo", "name": "Apollo 17 rover", "kind": "Lunar Roving Vehicle", "world": "moon", "years": "1972", "place": "Taurus\u2013Littrow", "status": "Parked on the Moon", "image": "lunar-rover.svg", "headline": "The last parking spot.", "number": "01", "facts": [["DESTINATION", "The Moon"], ["MISSION", "Apollo 17 \u00b7 1972"], ["LEFT BEHIND", "Lunar rover"]], "story": "For three excursions, an electric rover helped Gene Cernan and Harrison Schmitt explore the Taurus\u2013Littrow valley. Before departing, Cernan drove it to a final parking spot about 158 metres from the lunar module. Its television camera watched the astronauts lift off.", "legacy": "The rover could not come home. It remains on the Moon, alongside the descent stage and equipment from the mission. The tracks are a record of where people went\u2014and the samples they collected still give scientists new questions to ask.", "timeline": [["7 Dec 1972", "Launch from Earth"], ["11 Dec 1972", "Lunar landing"], ["14 Dec 1972", "Crew leaves the Moon"]], "source": "https://www.nasa.gov/history/50-years-ago-apollo-17-lands-at-taurus-littrow/", "sourceLabel": "NASA \u00b7 Apollo 17 at Taurus\u2013Littrow"}, {"id": "surveyor", "name": "Surveyor 3", "kind": "Robotic lunar lander", "world": "moon", "years": "1967", "place": "Oceanus Procellarum", "status": "Visited by Apollo 12", "image": "surveyor.svg", "headline": "The explorer we went back to.", "number": "02", "facts": [["DESTINATION", "The Moon"], ["LANDED", "20 April 1967"], ["VISITED", "November 1969"]], "story": "Before people stepped onto the Moon, Surveyor 3 tested its soil and sent back thousands of television images. Its sampler helped establish that the ground could support an Apollo lunar module. Contact ended on 4 May 1967.", "legacy": "In November 1969, Apollo 12 astronauts walked to the silent lander. They removed its camera and other parts for study on Earth. The rest stayed behind. Surveyor 3 became a rare case of humans revisiting a robotic explorer on another world.", "timeline": [["17 Apr 1967", "Launch"], ["20 Apr 1967", "Soft landing"], ["Nov 1969", "Apollo 12 visit"]], "source": "https://science.nasa.gov/mission/surveyor-3/", "sourceLabel": "NASA Science \u00b7 Surveyor 3"}, {"id": "opportunity", "name": "Opportunity", "kind": "Mars Exploration Rover \u00b7 MER-B", "world": "mars", "years": "2004\u20142018", "place": "Perseverance Valley", "status": "Last contact: June 2018", "image": "mars-rover.svg", "headline": "A short plan. An extraordinary life.", "number": "03", "facts": [["DESTINATION", "Mars"], ["DISTANCE", "45.16 kilometres"], ["LAST SIGNAL", "10 June 2018"]], "story": "Opportunity arrived with a planned prime mission of 90 Martian days. It kept exploring for more than 14 Earth years, following clues to a wetter Mars across 45.16 kilometres of terrain. Then a planet-wide dust storm darkened the sky and cut its solar power.", "legacy": "Its final signal reached Earth on 10 June 2018. Recovery attempts continued until NASA declared the mission complete in February 2019. The rover remains in Perseverance Valley. Its observations helped establish that ancient Mars had environments that could have supported microbial life\u2014not that life was found.", "timeline": [["July 2003", "Launched from Earth"], ["January 2004", "Arrived on Mars"], ["June 2018", "Final communication"]], "source": "https://science.nasa.gov/mission/mer-opportunity/", "sourceLabel": "NASA Science \u00b7 Opportunity"}, {"id": "spirit", "name": "Spirit", "kind": "Mars Exploration Rover \u00b7 MER-A", "world": "mars", "years": "2004\u20142010", "place": "Gusev crater", "status": "Silent since March 2010", "image": "spirit.svg", "headline": "Even a broken wheel found a way.", "number": "04", "facts": [["DESTINATION", "Mars"], ["DISTANCE", "7.73 kilometres"], ["OPERATIONS", "More than six years"]], "story": "Spirit explored Mars alongside its twin, Opportunity. A dragging wheel unexpectedly uncovered silica-rich soil\u2014evidence consistent with ancient hot springs or steam vents. A mechanical problem had become a scientific opportunity.", "legacy": "After becoming stuck in soft soil, Spirit continued working from one place. It fell silent in March 2010, and NASA ended recovery efforts in May 2011. The rover remains at Gusev crater, while its discoveries continue to shape our understanding of a once-wetter Mars.", "timeline": [["June 2003", "Launched from Earth"], ["January 2004", "Arrived at Gusev"], ["May 2011", "Mission declared complete"]], "source": "https://science.nasa.gov/mission/mer-spirit/", "sourceLabel": "NASA Science \u00b7 Spirit"}, {"id": "viking", "name": "Viking 1", "kind": "Mars lander", "world": "mars", "years": "1976\u20141982", "place": "Chryse Planitia", "status": "Mission complete", "image": "viking.svg", "headline": "A new world, at ground level.", "number": "05", "facts": [["DESTINATION", "Mars"], ["LANDED", "20 July 1976"], ["LANDER", "Stationary laboratory"]], "story": "Viking 1 brought the Martian surface into focus from a fixed landing site. Its cameras, weather instruments, and biology experiments made the lander a laboratory on another planet, paired with an orbiter overhead.", "legacy": "The lander operated until November 1982, far beyond its original mission. Its biology experiments did not establish that life existed on Mars. Viking\u2019s results helped define the questions that later missions would pursue. The lander remains in Chryse Planitia.", "timeline": [["August 1975", "Launch"], ["July 1976", "Lander reaches Mars"], ["November 1982", "Lander communication ends"]], "source": "https://science.nasa.gov/mission/viking-1/", "sourceLabel": "NASA Science \u00b7 Viking 1"}, {"id": "insight", "name": "InSight", "kind": "Mars geophysical lander", "world": "mars", "years": "2018\u20142022", "place": "Elysium Planitia", "status": "Mission complete", "image": "insight.svg", "headline": "It stayed still. And looked deeper.", "number": "06", "facts": [["DESTINATION", "Mars"], ["LANDED", "26 November 2018"], ["PURPOSE", "Study the interior"]], "story": "InSight did not need to drive. From Elysium Planitia, it placed instruments on the ground and listened for seismic activity. By recording marsquakes, it helped scientists investigate the structure hidden beneath the surface.", "legacy": "Dust on the solar panels gradually reduced the power available to the lander, and the mission ended in December 2022. Its instruments remain on Mars. The measurements it returned continue to offer a way to look inside a planet we have barely touched.", "timeline": [["May 2018", "Launch"], ["November 2018", "Mars landing"], ["December 2022", "Mission ends"]], "source": "https://science.nasa.gov/mission/insight/", "sourceLabel": "NASA Science \u00b7 InSight"}];
